SELECT CASE WHEN YEAR(launch_date) < 2024 THEN 'before_2024' WHEN YEAR(launch_date) = 2024 THEN '2024' ELSE 'after_2024' END launch_cohort, SUM(CASE WHEN brand = 'Acme' THEN 1 ELSE 0 END) acme_count, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(category))) category_values FROM products GROUP BY CASE WHEN YEAR(launch_date) < 2024 THEN 'before_2024' WHEN YEAR(launch_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY launch_cohort LIMIT 1;
